insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"L’antiguitat a Catalunya"},{"n":"2","title":"La Catalunya romana"},{"n":"3","title":"El naixement de Catalunya"},{"n":"4","title":"La Catalunya feudal (s. xi -xii)"},{"n":"5","title":"L’expansió catalanoaragonesa (s. xiii -xiv)"},{"n":"6","title":"La crisi de la baixa edat mitjana (s. xiv i xv)"},{"n":"7","title":"Catalunya en la monarquia hispànica i la Guerra dels Segadors (s. xvi -xvii)"},{"n":"8","title":"La Guerra de Successió i l’Onze de Setembre"},{"n":"9","title":"Les transformacions del segle xviii"}]'::jsonb, '["El naixement de Catalunya se situa entre els segles segles ix i x.","Catalunya ha estat cruïlla de persones, pobles, cultures i religions que han contribuït a fixar la nostra cultura com ara la coneixem.","El substrat romà constitueix la base sobre la qual cristal·litzarà la cultura catalana.","Catalunya neix com a entitat política sobirana sota les mateixes circumstàncies que molts regnes medievals. En el nostre cas particular és conseqüència de la feblesa de la monarquia franca i de l’enfortiment dels comtats catalans sota el domini franc com a territori de frontera amb els sarraïns i que rebia el nom de Marca Hispànica.","L’expansió de la corona catalanoaragonesa es duu a terme en dues direccions: la Mediterrània i la peninsular. Com a conseqüència d’aquest fet compartim en els nostres dies una mateixa cultura i llengua amb València, les Illes Balears i la ciutat sarda de l’Alguer.","En el segle xiv neixen les principals institucions polítiques que han arribat fins als nostres dies, les Corts Catalanes, amb funcions legislatives, i la Diputació del General o Generalitat, que tenia encomanades tasques executives, així com el Consell de Cent, que era l’administració local de Barcelona. El Parlament de Catalunya i la Generalitat de Catalunya tal com els coneixem avui són hereus directes d’aquestes institucions medievals.","La decadència de Catalunya comença a la baixa edat mitjana com a conseqüència d’una crisi econòmica i demogràfica, de la crisi social i la política. Fruit d’aquesta crisi política es produeix una unió dinàstica amb Castella que desplaçarà el poder cap al regne veí.","La monarquia hispànica no suposa la pèrdua de la identitat política de Catalunya. Tanmateix, en aquest període es perden, entre d’altres, els territoris de la Catalunya Nord i de Sardenya com a conseqüència de les guerres europees.","La pèrdua de les llibertats col·lectives de Catalunya és conseqüència de la derrota militar de l’11 de setembre de 1714 davant de les tropes franceses i castellanes de Felip V en el que anomenem Guerra de Successió i que es produeix per la mort sense descendència del rei Carles II, i en què s’erigiren dos bàndols, els partidaris de l’arxiduc Carles i els de Felip d’Anjou.","La recuperació demogràfica, social i econòmica que impulsarà la reivindicació de la recuperació de les institucions catalanes es va produir al llarg del segle xviii com a conseqüència de les transformacions agràries i preindustrials."]'::jsonb, '["Amfiteatre","Anglicanisme","Calvinisme","Creixement vegetatiu","Estat feudal","Fòrum","Heretgia dels càtars","Iconografia","Indústria lítica","Inflació","Menestrals","Ocupació sarraïna","Prohoms","Termes","Usatges","Vassallatge"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=11'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=11', 11, 19, 19, null
  from public.topics t where t.slug = 'mossos-a1-historia-1'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
