select t.id, 'ca', '[{"n":"1","title":"El segle xix: la crisi de l’Antic Règim i la construcció de l’Estat liberal"},{"n":"2","title":"Catalunya, la industrialització i l’obrerisme"},{"n":"3","title":"La restauració borbònica i el catalanisme polític"},{"n":"4","title":"El primer terç del segle xx (1898-1931)"},{"n":"5","title":"La República i la Guerra Civil"},{"n":"6","title":"La dictadura franquista"},{"n":"7","title":"La Transició i la recuperació de l’autonomia"},{"n":"8","title":"La Catalunya del segle xxi"}]'::jsonb, '["La Revolució Francesa suposa el trencament amb l’Antic Règim a l’Europa continental. Aquest sistema arrenca de l’edat mitjana i es fonamenta en una divisió social que té associada un seguit de privilegis. La seva extensió des de França a la resta de territoris europeus es produeix per les guerres napoleòniques, que a Catalunya reben el nom de Guerra del Francès.","Aquest nou període històric es caracteritza per la introducció del capitalisme com a sistema econòmic, i a Catalunya, a diferència de la resta de l’Estat, suposarà la industrialització i l’aparició de l’obrerisme al nostre país. La segona característica d’aquest període és la consolidació dels estats moderns. L’Estat espanyol serà incapaç d’estructurar un model sòlid i durador; aquest fet és la causa de les convulsions polítiques que caracteritzen aquest període i que arriben fins als nostres dies, en l’actual marc de reclamacions competencials protagonitzat entre les institucions catalanes i les estatals.","En el segle xix apareixen un seguit de moviments de caire polític i social. Apareixen les organitzacions obreres, que lluiten pels drets dels treballadors, i el catalanisme polític, que iniciarà la tasca de recuperació de les llibertats col·lectives perdudes a la Guerra de Successió: es reclama l’autogovern.","Paral·lelament al catalanisme polític, apareix un moviment de recuperació cultural que anomenem la Renaixença, que pretén recuperar la consciència diferencial catalana a través de la cultura.","El catalanisme polític es desenvoluparà al primer terç del segle xx i té en Solidaritat Catalana un dels exponents més clars d’aquesta expansió.","La Setmana Tràgica i els anys del pistolerisme ens mostren les tensions socials enmig d’una societat desigual i injusta.","La Segona República suposa la recuperació de les llibertats polítiques de Catalunya, que s’havia iniciat a principis del segle xx amb la Mancomunitat d’Enric Prat de la Riba, mentor del catalanisme. En aquest període són presidents de la Generalitat Francesc Macià i Lluís Companys, que morirà afusellat per les tropes colpistes del general Franco.","La insurrecció feixista del general Franco i la seva victòria militar a la Guerra Civil suposen, de nou, la pèrdua de les llibertats públiques de Catalunya, així com l’exili i la mort per a milers de catalans i una repressió política i cultural que durarà els quaranta anys que s’estengué el seu règim dictatorial.","La mort del dictador obre la porta vers la democràcia. Aquest període de transformació democràtica rep el nom de Transició. Així, es restitueixen les institucions catalanes i torna de l’exili el president de la Generalitat, Josep Tarradellas. S’aprova l’actual Constitució i l’Estatut d’autonomia de Catalunya, l’Estatut de Sau. El 20 de març de 1980 s’escull el primer president electe de Catalunya en aquesta nova etapa de la nostra història. Serà Jordi Pujol, el 126è president des de la fundació de la Generalitat amb Berenguer de Cruïlles l’any 1359.","El nou Estatut, aprovat en referèndum pel poble de Catalunya el 2006, fou anul·lat, en algunes de les seves disposicions, l’any 2010 pel Tribunal Constitucional. Aquest fet obrí una crisi de relacions entre les institucions catalanes i les espanyoles.","Pasqual Maragall fou president de la Generalitat del 2003 al 2006, José Montilla del 2006 al 2010, Artur Mas del 2010 al 2015. Carles Puigdemont del 10 de gener de 2016 al 27 d’octubre de 2017, cessat per l’aplicació de l’art. 155 de la CE. Joaquim Torra del 14 de maig de 2018 fins l’actualitat.","El Govern espanyol va convocar per al 21 de desembre de 2017 noves eleccions a Catalunya i, el 14 de maig de 2018, el Parlament va elegir nou president de la Generalitat de Catalunya Joaquim Torra. La presa de possessió del nou Govern el 2 de juny de 2018 va deixar sense efecte l’aplicació de l’art. 155 de la CE a Catalunya."]'::jsonb, '["Absolutisme","Antic Règim","Autarquia","Cabiles rifenyes","Desamortització","Governs tecnòcrates","Lerrouxisme","Les Tres Classes de Vapor","Ludisme","Mesures liberals (liberalisme)","Mesures proteccionistes","Partits dinàstics","Rabassaires","Sindicalisme vertical","Tesis bakuninistes","Trotskisme"]'::jsonb, '[{"text":"Esmena oficial (setembre 2026) a la llista de presidents de la Generalitat: Quim Torra, del 17/05/2018 al 28/09/2020; Pere Aragonès, del 24/05/2021 al 10/08/2024; Salvador Illa, des del 10/08/2024.","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Esmenes-edicio-PDF-guia-estudi-setembre-2026.pdf"}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=20'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=20', 20, 31, 30, null
  from public.topics t where t.slug = 'mossos-a2-historia-2'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
