insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema A.3, pp. 32-38', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=32', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
insert into public.topics (slug, title) values ('mossos-a3-historia-policia', 'A.3 Història de la policia a Catalunya') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'mossos-esquadra' and t.slug = 'mossos-a3-historia-policia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Les forces de seguretat i la seva història"},{"n":"2","title":"L’origen dels Mossos d’Esquadra"},{"n":"3","title":"Transformacions policials durant el segle xix"},{"n":"4","title":"La policia durant les primeres dècades del segle xx"},{"n":"5","title":"La policia i la democràcia"}]'::jsonb, '["Una de les bases del manteniment de l’odre públic a Catalunya fou la defensa de la Pau i Treva.","La institucionalització del cos policial dels Mossos d’Esquadra va tenir lloc entre 1719 i 1721.","Els Mossos d’Esquadra es convertirien durant el segle xviii en un precedent de la policia moderna.","Durant el segle xix el Mossos continuarien la seva tasca, tot i la formació del cos policial unificat a tota Espanya de la Guàrdia Civil a partir de la meitat de segle.","El desenvolupament de les guàrdies urbanes va ser important a partir del segle xix amb el creixement urbanístic, i en destaca la formació de la Guàrdia Urbana de Barcelona el 1843.","A partir de l’abril de 1931, amb la República, les Esquadres no tan sols es van mantenir sinó que van adaptar-se al nou règim i van agafar un tarannà diferent del que havien tingut fins aquell moment. Van passar a ser identificades amb les institucions pròpies i amb el govern català, lleials als presidents de la Generalitat i vinculades al projecte populista republicà i catalanista d’aquells anys.","Durant la Guerra Civil, la policia es va veure immersa en les vicissituds històriques i va ser fidel al Govern de la Generalitat durant l’aixecament militar colpista.","El règim franquista fou un règim policial on es barrejaven els interessos del règim amb les tasques policials i militars i el partit únic era considerat un braç més de la policia.","Amb la restauració de la Generalitat i l’Estatut d’autonomia, els Mossos d’Esquadra esdevenen la policia de Catalunya, arrelada a l’imaginari col·lectiu, professionalment ben preparada i coincident amb els pressupòsits d’una societat avançada i democràtica."]'::jsonb, '["Cossos policials","Desplegament","Esquadres de Catalunya","Exèrcit popular","Fur militar","Guàrdia Civil","Guàrdia Urbana","Inquisició","Jurisdicció","Milícia Nacional","Mosso d’Esquadra","Ordre públic","Pau i Treva","Policia democràtica","Policia integral","Policia de Catalunya","Reial Audiència","Règim policial","Sistema de seguretat"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=32'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=32', 32, 38, 38, null
  from public.topics t where t.slug = 'mossos-a3-historia-policia'
