insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Història de la llengua"},{"n":"1.1","title":"Segles vii a xii: orígens i formació"},{"n":"1.2","title":"Segles xiii a xv: expansió i consolidació"},{"n":"1.3","title":"Segles xvi a xviii: retrocés de la llengua"},{"n":"1.4","title":"Segle xix: recuperació lingüística"},{"n":"1.5","title":"Segle xx i xxi: la normativització"},{"n":"2","title":"Varietats lingüístiques"},{"n":"2.1","title":"Segons els parlants"},{"n":"2.2","title":"Segons l’ús: registres"},{"n":"2.3","title":"La varietat estàndard"},{"n":"3","title":"La llengua aranesa"},{"n":"3.1","title":"El règim especial d’Aran"},{"n":"3.2","title":"Reconèixer, protegir i promoure l’occità"},{"n":"4","title":"Noves versions de la Gramàtica de la llengua catalana i de l’Ortografia catalana"}]'::jsonb, '["El català és una llengua romànica que prové del llatí popular, parlat, portat al territori pels soldats i mercaders, i no pas del llatí culte o literari. El llatí popular és l’element bàsic en la formació del català.","Diglòssia: la convivència de dues llengües en què una, la llengua A (alta, amb més prestigi), expressa tots els àmbits de poder –administració, ensenyament, literatura, comerç, usos públics– i l’altra, la llengua B (baixa, amb menys prestigi), només s’usa en els àmbits privats.","El naixement de la prosa literària catalana comença a la segona meitat del segle xiii, amb l’obra extraordinària del mallorquí Ramon Llull. L’hegemonia política i l’afermament de la Corona (conquestes de Mallorca, València i Sicília) consolidaran una consciència d’identitat i convertiran la llengua en un factor de coherència cultural i política.","Pere el Cerimoniós va ser el primer rei català que va intuir l’estret lligam entre el poder i la llengua. Aquesta interrelació s’estendrà per tots els territoris dominats per la Corona i la llengua catalana arribarà a ser una de les llengües més esteses i difoses.","La Cancelleria reial és un organisme administratiu i burocràtic que té la tasca de redactar els documents oficials de la Corona, i que són considerats models de bona escriptura; un model d’escriptura acadèmica que avui anomenaríem llengua estàndard, perquè codifica i unifica la llengua a tot el territori.","Al llarg del segle xiv i inici del xv, en les relacions formals (administració, cort pontifícia, ciència, pensament i literatura) s’usa el català com a llengua de prestigi. En les relacions informals de la vida íntima i familiar s’usa exclusivament la llengua catalana.","Al segle xv s’escriuen les grans novel·les de la literatura medieval catalana i s’assoleixen moments d’esplendor.","La unió dinàstica amb els Trastàmara (1412) no va tenir, en principi, cap repercussió immediata en l’àmbit lingüístic ni va alterar la condició del català. Ara bé, la llengua dels monarques i de la cort era el castellà, la qual cosa provocaria el procés de canvi lingüístic. Per al poble, però, el castellà era una llengua desconeguda al segle xv.","Des del segle xvi fins al xviii hi ha un retrocés de la llengua catalana perquè hi ha una pèrdua de consciència lingüística, no es produeixen tantes obres cultes i de creació com al segle anterior, i perquè la Corona d’Aragó queda lligada definitivament al projecte de monarquia dels Reis Catòlics.","Fins al darrer terç del segle xvii, l’ús social de la llengua es manté ben viu en les relacions familiars, a l’església, a l’administració, a l’escola, en els llibres tècnics i d’història, en els llibres de comptes públics i privats, en els documents notarials, en els testaments...","A partir del darrer terç del segle xvii l’administració deixa d’usar-lo a causa de la presència del funcionariat castellà, de la inquisició, de l’adhesió de les classes altes al castellà i del prestigi que té aquesta llengua davant dels estaments burgesos i populars.","El 1659 Castella i França signen el Tractat dels Pirineus, pel qual el Rosselló (el Conflent, el Capcir, el Vallespir) i la meitat de la Cerdanya passen a sobirania francesa. En aquests territoris de seguida es va prohibir el català en l’ensenyament, i el 1700 se’n va prohibir l’ús en els documents públics amb un edicte de Lluís XIV.","La Guerra de Successió (1702-1714), i el seu desenllaç, marcaran l’inici d’una nova etapa. Guanyada la guerra pels partidaris de Felip d’Anjou, es dicten els decrets de Nova Planta, que anul·len l’oficialitat del català i el prohibeixen: el 1707 a València, el 1715 a les Illes Balears (excepte a Menorca, sota dominació anglesa) i el 1716 al Principat de Catalunya.","Al llarg dels segles xviii i xix aniran apareixent nous decrets i mesures per prohibir el català a l’escola, als tribunals civils i eclesiàstics, al teatre, als llibres de comptabilitat... Ara bé, la major part de la població era analfabeta i no entenia cap altra llengua que no fos la catalana.","A partir de la segona meitat del segle xix hi ha una represa de consciència nacional, i els intel·lectuals i la burgesia, enfortida per la industrialització, volen recuperar els signes d’identitat.","L’any 1859, Joaquim Rubió i Ors, Manuel Milà i Fontanals, Víctor Balaguer i Antoni de Bofarull restableixen els Jocs Florals, peça clau en la restauració de la llengua.","El període 1900-1939 significa la codificació de l’estàndard i l’ús social de la llengua, a partir d’una sèrie de fets decisius per a l’estudi científic del català.","L’any 1906 es convoca el Primer Congrés Internacional de la Llengua Catalana, a iniciativa de Mossèn Antoni M. Alcover. Té un gran ressò popular, amb molt d’èxit d’inscripció, uns 4.000 congressistes, procedents tant de tot l’àmbit lingüístic català com de l’àrea internacional.","L’any 1913 Pompeu Fabra publica les Normes ortogràfiques; el 1917, el Diccionari Ortogràfic; el 1918, la Gramàtica Catalana, i el 1932, el Diccionari General de la Llengua Catalana. Intel·lectuals i escriptors valencians accepten les normes de Fabra: Normes de Castelló.","L’any 1931 s’instaura la II República. S’aconsegueixen avenços en la normalització lingüística: l’ensenyament a les escoles i la difusió en els mitjans de comunicació de premsa i ràdio. F. B. Moll publica l’Ortografia mallorquina segons les normes de l’Institut.","Des de l’any 1939 fins al 1975 hi ha una nova repressió de la cultura catalana: es prohibeix l’ús del català en tots els àmbits públics. Les institucions catalanes s’aboleixen (Generalitat, IEC, etc.) i molts intel·lectuals han de fugir a l’exili, on es farà una tasca important de manteniment de la cultura.","Al final del règim dictatorial hi ha una certa tolerància: tímida publicació de textos; apareixen revistes, editorials i noves generacions d’escriptors, i el 1961 es crea Òmnium Cultural, que comença a ensenyar el català.","Amb la mort de Franco, comença la transició política, i s’instaura la democràcia, que marca la recuperació de les institucions nacionals, les quals retornen de l’exili. Com que ja s’havia fet la normativització de la llengua, és el moment d’iniciar la normalització del coneixement i de l’ús, a partir d’un nou marc legal.","Una llengua no és mai uniforme ni fixa. Les varietats lingüístiques són les diferents modalitats d’una mateixa llengua. Per damunt de totes les varietats hi ha la varietat estàndard. Podem classificar les varietats segons els parlants o segons l’ús.","La llengua catalana ha estat i és la llengua pròpia de Catalunya, és a dir, la llengua pròpia del territori, i és l’element fonamental de formació de la cultura catalana.","Aran constitueix dins Catalunya una realitat nacional amb personalitat pròpia i diferenciada, fonamentada en el fet que la comunitat aranesa disposa d’una llengua i una cultura pròpies, comunes i compartides amb la resta d’Occitània, i, alhora, d’una antiga tradició d’autogovern fermament defensada pels aranesos al llarg del temps.","L’aprovació de l’Estatut d’autonomia de Catalunya del 2006 va suposar un nou i decisiu pas endavant en el ple reconeixement de la realitat nacional occitana d’Aran i, alhora, un canvi fonamental respecte de la situació precedent amb relació a l’oficialitat de la llengua pròpia de la comunitat aranesa.","La Llei 35/2010, de l’1 d’octubre, de l’occità, aranès a l’Aran, té per objectius generals reconèixer, protegir i promoure l’occità d’acord amb la seva varietat aranesa en tots els àmbits i sectors.","L’oficialitat de l’occità s’estén, a més, a tot Catalunya, que esdevé així l’únic territori dins l’Estat que reconeix tres llengües oficials."]'::jsonb, '["Aran","Cancelleria reial","Codificació de l’estàndard","Consciència d’identitat","Decrets i mesures","Diglòssia","Funcionariat castellà","Guerra de Successió","Hegemonia política","IEC","Jocs Florals","Literatura medieval","Llei 35/2010, de l’1 d’octubre, de l’occità","Llengua de prestigi","Llengua pròpia","Llengua romànica","Normalització","Normativització","Nova repressió","Òmnium Cultural","Poder i llengua","Pompeu Fabra","Primer Congrés Internacional de la Llengua Catalana","Realitat nacional occitana d’Aran","Represa de consciència nacional","Retrocés de la llengua","Toponímia","Tractat dels Pirineus","Transició política","Trastàmara","Unió dinàstica","Ús social de la llengua"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=39'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=39', 39, 56, 54, null
  from public.topics t where t.slug = 'mossos-a4-sociolinguistic'
