insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema A.5, pp. 57-66', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=57', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
insert into public.topics (slug, title) values ('mossos-a5-marc-geografic', 'A.5 Marc geogràfic de Catalunya') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'mossos-esquadra' and t.slug = 'mossos-a5-marc-geografic' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Situació i divisió administrativa"},{"n":"2","title":"El relleu"},{"n":"2.1","title":"El Pirineu"},{"n":"2.2","title":"La Depressió Central"},{"n":"2.3","title":"El Sistema Mediterrani"},{"n":"2.4","title":"La Serralada Transversal"},{"n":"2.5","title":"Les planes litorals i la costa"},{"n":"3","title":"Els climes a Catalunya"},{"n":"3.1","title":"Les temperatures"},{"n":"3.2","title":"Les precipitacions"},{"n":"4","title":"La xarxa hidrogràfica"},{"n":"5","title":"La vegetació"},{"n":"6","title":"La població"},{"n":"6.1","title":"Evolució de la població"},{"n":"6.2","title":"Distribució de la població"}]'::jsonb, '["Administrativament, Catalunya s’organitza en vuit vegueries, 42 comarques i 947 municipis.","Catalunya no configura cap unitat fisiogràfica determinada i es caracteritza per una gran diversitat paisatgística. A partir de la interacció de factors físics, socials, econòmics i culturals, s’ha anat conformant una important varietat comarcal.","Catalunya està formada per tres grans unitats de relleu, que són els Pirineus, la Depressió Central i el Sistema Mediterrani. El litoral català, per la seva banda, està constituït per planes litorals, costes i alguns deltes.","A Catalunya, el clima és de tipus mediterrani temperat. La complexitat orogràfica de Catalunya i la proximitat a la mar Mediterrània fan que tinguin rellevància factors com el relleu i la continentalitat, que donen lloc a altres varietats climàtiques.","Els rius catalans presenten règims fluvials molt diferents i irregulars, fet que provoca l’existència de diferents xarxes hidrogràfiques.","La variada orografia i el clima fan que a Catalunya hi trobem una gran diversitat de paisatges vegetals. La vegetació potencial a Catalunya pertany a tres grans regions biogeogràfiques: la regió mediterrània, la regió eurosiberiana i la regió boreoalpina.","La població de Catalunya ha tingut tres grans períodes de creixement en els darrers 100 anys. L’últim ha estat protagonitzat per persones procedents de l’estranger, cosa que ha provocat una heterogeneïtzació de la societat catalana.","La distribució de la població a Catalunya és molt irregular, amb una concentració del 64% a la RMB."]'::jsonb, '["Altiplà","Altitud","Anticicló","Àrea Metropolitana de Barcelona","Boscos caducifolis","Comarca","Conques d’erosió","Continentalitat","Densitat de població","Esperança de vida","Fluxos de mobilitat","Índex de fecunditat","Ombra pluviomètrica","Onada immigratòria","Orografia","Planes deltaiques","Planes tectòniques","Règim pluvial","Règim pluvionival","Regió Metropolitana de Barcelona","Relleu en costa","Unitat fisiogràfica","Valls fluvials","Vegetació potencial","Vegueria","Xarxa fluvial"]'::jsonb, '[{"text":"Esmena oficial (setembre 2026): Catalunya té 42 comarques més l’Aran com a entitat territorial singular (p. 56 i punt 1 de la p. 64), 947 municipis i 8 vegueries.","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Esmenes-edicio-PDF-guia-estudi-setembre-2026.pdf"}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=57'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=57', 57, 66, 66, null
  from public.topics t where t.slug = 'mossos-a5-marc-geografic'
