insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La migració a Catalunya i fluxos migratoris"},{"n":"1.1","title":"Les migracions contemporànies"},{"n":"1.2","title":"La immigració a Espanya i Catalunya"},{"n":"1.3","title":"La dinàmica migratòria i l’evolució de la població catalana"},{"n":"2","title":"Les polítiques públiques en matèria d’immigració"},{"n":"2.1","title":"Política migratòria comunitària"},{"n":"2.2","title":"Política migratòria d’Espanya i Catalunya"},{"n":"3","title":"Models d’integració i marcs de convivència en la societat multicultural"},{"n":"4","title":"Les polítiques públiques en matèria d’igualtat d’oportunitats"},{"n":"5","title":"Els serveis socials a Catalunya"},{"n":"5.1","title":"L’Estat del benestar i la provisió de serveis"},{"n":"5.2","title":"Els serveis socials"}]'::jsonb, '["Durant les últimes dècades s’han consolidat noves pautes migratòries internacionals que han contribuït a generalitzar els moviments migratoris de manera important. Podem destacar tres dimensions en què es percep aquest caràcter del fenomen migratori: el creixement constant del volum de persones migrants, l’ampliació de les xarxes i cadenes migratòries, i la diversificació dels tipus migratoris.","L’Estat espanyol s’ha convertit, durant les últimes quatre dècades, en un important centre de recepció d’immigració.","Catalunya es troba inserida en el context de globalització i intensificació dels fluxos que caracteritza les migracions internacionals de les últimes dècades del segle xx i principis del segle xxi.","La dècada dels vuitanta es va caracteritzar per una acceleració de la immigració, de manera que el nombre d’estrangers a Catalunya gairebé va duplicar-se, guanyant pes relatiu en el conjunt de la societat catalana.","La immigració estrangera a Catalunya es nodreix d’un doble flux: d’una banda, l’arribada d’europeus, i de l’altra, una creixent immigració de països extracomunitaris.","A l’hora de definir les pautes de convivència amb què es definiran les estratègies i polítiques socials en societats que reben fluxos migratoris, les ciències socials diferencien tres grans models: assimilació, melting pot –gresol cultural– i pluralisme cultural.","La ràpida acceleració dels fluxos, la seva afectació múltiple i el seu interès en relació amb el món laboral han donat lloc al desenvolupament d’una normativa que regula aquesta immigració des d’un punt de vista legal. Aquest marc legal ve determinat pel fet de pertànyer a la UE i a més de la competència de l’Estat, hi hem d’afegir les iniciatives preses per la Generalitat i els ajuntaments en diferents àmbits.","L’estat de benestar es defineix com el conjunt de polítiques l’objectiu de les quals és millorar les condicions de vida de la ciutadania i assegurar la igualtat d’oportunitats. Es fonamenta en transferències socials, serveis, i intervencions.","L’estat social i democràtic de dret consagra el principi d’igualtat i no-discriminació, entre d’altres, per raó de sexe, i el configura com un dret subjectiu a tenir un tracte igual, però l’existència del reconeixement d’aquest dret no significa que en la realitat, en la vida quotidiana, no es donin situacions que de fet són discriminatòries.","Les polítiques públiques són aquelles decisions adoptades pels òrgans de govern, ja sigui mitjançant normes, disposicions, estratègies, plans d’actuació o actes, i que tenen per objecte determinar les actuacions que el govern planifica o executa en relació amb una matèria concreta.","Les polítiques d’igualtat d’oportunitats consisteixen en la determinació i adopció de mesures per part de les institucions públiques amb l’objectiu de pal·liar i resoldre les situacions de desigualtat social entre homes i dones.","A Catalunya, les polítiques a favor de la igualtat d’oportunitats entre homes i dones es desenvolupen a través de plans plurianuals que s’elaboren, planifiquen i executen de manera conjunta entre diferents departaments de la Generalitat de Catalunya.","Des de la seva creació el 1989, l’Institut Català de les Dones té el repte de dissenyar estratègies de transversalitat que garanteixin que totes les polítiques incorporin la perspectiva de gènere i de les dones especialment per afavorir la conciliació de la vida familiar i professional de les dones i dels homes i erradicar la violència contra les dones.","El sistema català de serveis socials constitueix un recurs a l’abast de tota la ciutadania i té com a destinatàries totes les persones que necessiten informació, valoració, diagnòstic, orientació, suport, intervenció i assessorament individual, familiar o comunitari per fer front i prevenir situacions de necessitat personal bàsica, de manca de cohesió social o familiar o de desigualtat."]'::jsonb, '["Acollida","Aculturació","Asil","Assimilació","Cadena migratòria","Canvi social","Ciutadania","Cohesió social","Conciliació","Desplaçats","Desigualtat social","Diversitat sociocultural","Emigració","Entrada clandestina","Estrangeria","Estrangers de “tercers països”","Exclusió social","Gènere","Globalització","Gresol cultural","Igualtat d’oportunitats","Immigració extracomunitària","Immigració permanent o de llarga durada","Llibertat de circulació","Marcs de convivència","Migracions","Minories ètniques o culturals","Models d’integració","Multidimensional","Nacionalitat per residència","Població autòctona","Polítiques públiques","Protecció internacional","Pluralisme cultural","Refugi","Regularització","Serveis socials","Tipologies migratòries","Transferències socials","Violència masclista"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=67'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=67', 67, 82, 81, null
