insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema A.7, pp. 83-93', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=83', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
insert into public.topics (slug, title) values ('mossos-a7-tic', 'A.7 Les tecnologies de la informació en el segle XXI') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'mossos-esquadra' and t.slug = 'mossos-a7-tic' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La societat del coneixement i les tecnologies de la informació. Internet i la Internet de les coses (IoT)"},{"n":"2","title":"Efectes de les tecnologies de la informació i la comunicació (TIC)"},{"n":"3","title":"Seguretat de la informació"},{"n":"4","title":"L’administració electrònica. Signatura electrònica"},{"n":"5","title":"Comunicació i control públic: espais de seguretat i alarmes socials"},{"n":"6","title":"La intel·ligència artificial (IA) i l’automatització de processos"}]'::jsonb, '["La societat postindustrial de la segona meitat del segle xx dona pas a la societat informatitzada, la cibersocietat, que es caracteritza per considerar la informació com la principal riquesa i font d’organització.","El que caracteritza la societat de la informació és que, gràcies a les TIC, la transmissió d’aquesta informació arriba a un nombre enorme d’usuaris, amb una rapidesa i immediatesa impensables fins fa ben poc, i amb un volum tan gran que allò difícil és, justament, processar en l’àmbit personal la gran quantitat d’informació que es rep diàriament.","La Internet de les coses esdevé un nou paradigma en relació amb la xarxa d’Internet, ja que fa créixer de manera exponencial el volum de dispositius interconnectats juntament amb noves formes d’amenaces.","La seguretat de la informació ha de ser un element bàsic a l’hora de gestionar les organitzacions. Així, cal enfocar-la com un objectiu global de caràcter intern.","Cada vegada és més important la qualitat de la informació i el coneixement rebuts que la quantitat. Les persones han d’aprendre a valorar i seleccionar la informació abans de processar-la. Internet és una immensa xarxa de computadores estesa per tot el planeta i que permet, a qualsevol usuari, conèixer arxius d’informació i de dades, amb so i imatges animades o estàtiques, gràfics, etc., a partir d’adreces electròniques o bé mitjançant programari que permet navegar a la recerca d’informació de tota mena des de qualsevol punt del món.","L’administració electrònica és un model de relació entre els ciutadans i l’Administració que aspira a millorar la prestació dels serveis als ciutadans, les empreses i les entitats, i a augmentar la productivitat d’aquests serveis i la participació ciutadana mitjançant l’ús de les tecnologies de la informació i la comunicació.","Gràcies a la signatura electrònica és possible garantir conceptes clau com l’autenticitat, la integritat i el no repudi en el si de les comunicacions electròniques.","Un dels perills més patents que avui dia pot comportar Internet és la seva manca de regulació, però, sobretot, que la innovació també es doni en noves formes de delictes contra els drets de les persones.","La IA representa una evolució de les tecnologies de la informació que permet l’automatització de processos i la presa de decisions assistida a partir de l’anàlisi massiva de dades, fet que obre noves oportunitats però també nous reptes en matèria de seguretat, control i garantia dels drets fonamentals."]'::jsonb, '["Automatització","Administració electrònica","Avenç tecnològic","Cibercultura","Cibersocietat","Comerç electrònic","Dades confidencials","Globalització","Hipermèdia","Hipertext","Informàtica","Innovació tecnològica","Interactivitat","Internet de les coses","Multimèdia","Obsolescència","Realitat virtual","Robotització","Sector de serveis, terciari","Sector industrial, secundari","Seguretat de la informació","Signatura electrònica","Sistemes de comunicació","Societat postindustrial","Tècnica","Tecnologies de la informació i la comunicació","Transaccions","Universitat oberta"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=83'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=83', 83