insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Antecedents històrics i naturalesa jurídica"},{"n":"1.1","title":"Antecedents històrics"},{"n":"1.2","title":"Naturalesa jurídica"},{"n":"2","title":"Contingut i estructura"},{"n":"2.1","title":"Contingut"},{"n":"2.2","title":"Estructura"},{"n":"3","title":"Els drets, els deures i els principis rectors"},{"n":"4","title":"Les competències de la Generalitat de Catalunya"},{"n":"4.1","title":"Tipologia"},{"n":"4.2","title":"Principis i criteris"},{"n":"4.3","title":"Les matèries de les competències"},{"n":"5","title":"La competència en matèria de seguretat pública establerta a l’Estatut d’autonomia de Catalunya"}]'::jsonb, '["L’Estatut d’autonomia de Catalunya és la norma institucional bàsica de la Comunitat Autònoma de Catalunya.","La Generalitat és el sistema institucional en què s’organitza l’autogovern de Catalunya. Els poders de la Generalitat emanen del poble de Catalunya i s’exerceixen d’acord amb el que estableixen l’EAC i la Constitució.","El català és la llengua d’ús normal i preferent de les administracions públiques.","L’EAC incorpora un catàleg de drets, deures i principis rectors que informa la condició política de ciutadania.","La regulació que fa l’EAC de les competències de la Generalitat pretén garantir i ampliar el nivell competencial autonòmic.","L’EAC preveu els mecanismes perquè la Generalitat participi com a tal en les institucions i en la fixació de polítiques de l’Estat, disposi de mecanismes àgils de col·laboració i cooperació amb les comunitats autònomes, sigui present i faci sentir la seva veu davant les institucions europees i impulsi la projecció exterior, i promogui el interessos de Catalunya, tot respectant les competències estatals.","La Generalitat té el comandament de la Policia de la Generalitat - Mossos d’Esquadra i la coordinació de l’actuació de les policies locals.","La Policia de la Generalitat - Mossos d’Esquadra exerceix les funcions en els àmbits de la seguretat pública i l’ordre públic, la policia administrativa, i la policia judicial i la investigació criminal."]'::jsonb, '["Bloc de constitucionalitat","Competències compartides","Competències exclusives","Competències executives","Convenis de col·laboració","Estatut d’autonomia","Policia de la Generalitat - Mossos d’Esquadra","Policies locals","Seguretat pública","Sistema institucional"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=94'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=94', 94, 106, 106, null
