insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema B.2, pp. 107-117', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=107', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
insert into public.topics (slug, title) values ('mossos-b2-institucions-catalunya', 'B.2 Les institucions polítiques de Catalunya') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'mossos-esquadra' and t.slug = 'mossos-b2-institucions-catalunya' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La Generalitat de Catalunya"},{"n":"2","title":"El Parlament de Catalunya"},{"n":"3","title":"La Presidència de la Generalitat de Catalunya"},{"n":"4","title":"El Govern i l’Administració de la Generalitat de Catalunya"},{"n":"5","title":"Altres institucions estatutàries"},{"n":"5.1","title":"El Consell de Garanties Estatutàries"},{"n":"5.2","title":"El Síndic de Greuges"},{"n":"5.3","title":"La Sindicatura de Comptes"},{"n":"5.4","title":"El Consell de l’Audiovisual de Catalunya"}]'::jsonb, '["La Generalitat és la institució en què s’organitza políticament l’autogovern de Catalunya, que comprèn bàsicament el Parlament, la Presidència de la Generalitat i el Govern.","El Parlament de Catalunya és l’assemblea representativa i legislativa de Catalunya i, com a tal, aprova els pressupostos i impulsa i controla l’acció política del Govern.","Per assegurar la independència i la llibertat del Parlament davant la resta de poders públics, els diputats gaudeixen de tres prerrogatives (garanties per al bon exercici de la seva funció): la inviolabilitat, la immunitat i el fur; i no estan sotmesos a mandat imperatiu.","L’EAC assigna al Parlament quatre grans funcions: la funció representativa, la legislativa, la funció de creació i control del Govern, i la funció de participació en l’activitat dels òrgans centrals de l’Estat.","El poder executiu de la Generalitat correspon a dues institucions bàsiques estretament relacionades, que són la Presidència de la Generalitat i el Govern, que és l’òrgan que dirigeix l’acció política i l’Administració de la Generalitat i és titular de la funció executiva i de la potestat reglamentària.","El/la president/a de la Generalitat ha de ser elegit pel Parlament de Catalunya entre els seus membres, per majoria absoluta en primera votació, o per majoria simple al cap de 48 hores.","La Presidència de la Generalitat té atribuïda una triple vessant: és el cap del Govern, el president de la Comunitat Autònoma de Catalunya i el representant ordinari de l’Estat a Catalunya.","Anomenem institucions de rellevància estatutària les que preveu l’EAC. Són institucions catalanes de rellevància estatutària el Consell de Garanties Estatutàries, el Síndic de Greuges, la Sindicatura de Comptes i el Consell de l’Audiovisual de Catalunya."]'::jsonb, '["Assemblea representativa","Autonomia reglamentària","Compareixença","Consellers","Delicte flagrant","Demarcació electoral","Dictamen","Diputat","Drets fonamentals","Enjudiciar","Ens públic","Examen d’incompatibilitats","Història secular","Inculpació","Majoria parlamentària","Majoria simple","Moció de censura","Negligència","Òrgan de fiscalització","Òrgan rector col·legiat","Òrgan unipersonal","Organisme consultiu","Ple","Portaveu","Potestat reglamentària","Preceptiu","Prerrogatives","Processament","Qüestió de confiança","Recurs d’inconstitucionalitat","Règim parlamentari","Responsabilitat penal","Sistema institucional","Sistema parlamentari","Sobirania popular","Sufragi universal","Vinculant"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=107'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=107', 107, 117, 117, null
