insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"L’ordenament jurídic"},{"n":"1.1","title":"Noció i característiques de l’ordenament jurídic espanyol"},{"n":"1.2","title":"Les regles de relació entre normes i entre ordenaments"},{"n":"1.3","title":"Les fonts"},{"n":"2","title":"La Constitució espanyola"},{"n":"2.1","title":"La Constitució com a norma suprema"},{"n":"2.2","title":"Contingut i estructura de la Constitució espanyola"},{"n":"3","title":"La llei"},{"n":"3.1","title":"El concepte de llei"},{"n":"3.2","title":"El procediment legislatiu ordinari"},{"n":"3.3","title":"Tipus de llei"},{"n":"4","title":"Les normes amb rang de llei"},{"n":"4.1","title":"El decret llei"},{"n":"4.2","title":"El decret legislatiu"},{"n":"5","title":"El reglament"},{"n":"5.1","title":"Concepte i posició en l’ordenament jurídic"},{"n":"5.2","title":"Classes de reglaments"},{"n":"5.3","title":"El control dels reglaments"},{"n":"6","title":"Els tractats internacionals"},{"n":"6.1","title":"Concepte"},{"n":"6.2","title":"La recepció interna dels tractats internacionals"},{"n":"6.3","title":"La posició dels tractats en el sistema de fonts"}]'::jsonb, '["L’ordenament jurídic espanyol està encapçalat per la Constitució. La Constitució és la norma que regula la producció de les altres normes jurídiques, obre la cadena de validesa i serveix de criteri interpretatiu de la resta de les normes jurídiques.","Les característiques de l’ordenament jurídic espanyol són: unitat, coherència, plenitud, dinamisme i pluralitat.","Un ordenament jurídic és un sistema tancat que pot estar format per diverses subestructures. Les seves relacions estan regides pel principi de competència entre ordenaments.","La Constitució espanyola (CE) és la norma suprema de l’ordenament jurídic, de la qual deriva la validesa de tota la resta de normes. És la norma jeràrquicament superior de l’ordenament jurídic espanyol perquè es diu que emana del poble, mitjançant els seus representants polítics, en exercici de la seva sobirania (poder constituent).","La llei és la norma jurídica aprovada pel Parlament (Corts Generals i assemblees legislatives de les comunitats autònomes) amb aquest caràcter i denominació que, en expressió del poder legislatiu i d’acord amb el procediment establert, regula les matèries no reservades per la CE a altres fonts del dret.","La llei és la norma de rang immediatament inferior a la Constitució i, per tant, no pot ser contrària a les disposicions de la norma fonamental; però, en la mesura que està elaborada pels representants del poble, se li concedeix un rang superior al de la resta de normes aprovades per altres òrgans de l’Estat.","A més de la llei ordinària, la CE preveu l’existència de diferents tipus o especialitats de lleis, en funció: del tràmit o procediment per aprovar-les (llei orgànica, llei de pressupostos, lleis de comissió i de lectura única); de la matèria que han de regular (llei orgànica, llei de pressupostos, llei de transferència o delegació, llei d’harmonització i llei marc), o de l’òrgan parlamentari que les aprovi (llei estatal o llei autonòmica).","Són lleis orgàniques: les que afecten el desenvolupament dels drets fonamentals o les llibertats públiques, les que aprovin els estatuts d’autonomia i les que afecten altres matèries no enumerades expressament per l’article 81 però previstes al llarg de l’articulat de la CE. Per tant, la distinció entre llei ordinària i llei orgànica es basa en la matèria que regulen i en el procediment d’aprovació (i de modificació i derogació, segons l’article 81 de la CE).","La CE atribueix al Govern la capacitat de dictar normes diferents dels reglaments, a les quals concedeix el mateix rang, força i valor que les lleis: el decret llei i el decret legislatiu. En qualsevol dels dos casos, però, la CE exigeix la intervenció de les Corts Generals en algun moment del procediment.","El Govern pot dictar reglaments, que són disposicions normatives de caràcter general subordinades a la llei.","Un tractat internacional és aquell acord escrit entre un o més estats pel qual les parts signants adquireixen determinats drets i obligacions, l’incompliment dels quals dona lloc a responsabilitat internacional davant les altres parts."]'::jsonb, '["Cadena de validesa","Clàusula de prevalença","Clàusula de supletorietat","Constitucionalitat","Delegació legislativa","Derogació","Derogació tàcita","Disposició addicional","Disposició derogatòria","Disposició final","Disposició transitòria","Disposicions legislatives provisionals","Disposicions normatives provisionals","Dret intern","Esmena","Estructura jeràrquica piramidal","Immutabilitat","Iniciativa legislativa","Llacunes normatives","Llei ordinària/ Llei orgànica","Norma suprema","Poder constituent","Principi de competència","Projecte de llei","Proposició de llei","Rang jeràrquic","Ratificació","Recurs","Reserva de llei","Supremacia"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=118'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=118', 118, 128, 127, null
