insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Les declaracions de drets humans"},{"n":"2","title":"Els drets fonamentals i les llibertats públiques"},{"n":"2.1","title":"Drets personals o de llibertat"},{"n":"2.2","title":"Drets de participació o polítics"},{"n":"2.3","title":"Drets econòmics i socials"},{"n":"3","title":"La titularitat dels drets constitucionals"},{"n":"3.1","title":"Nacionals"},{"n":"3.2","title":"Estrangers"},{"n":"4","title":"Els drets constitucionals relacionats amb el procés penal"},{"n":"4.1","title":"Dret a la llibertat (article 17 de la Constitució espanyola)"},{"n":"4.2","title":"Dret a la inviolabilitat del domicili (article 18.2 de la Constitució espanyola)"},{"n":"4.3","title":"Dret al secret de les comunicacions (article 18.3 de la Constitució espanyola)"},{"n":"4.4","title":"Dret a la tutela judicial efectiva (article 24.2 de la Constitució espanyola)"},{"n":"4.5","title":"Mesures de protecció integral sobre la violència sexual"},{"n":"5","title":"Les garanties normatives"},{"n":"5.1","title":"La vinculació de tots els poders públics als drets i les llibertats"},{"n":"5.2","title":"El principi de reserva de llei"},{"n":"5.3","title":"La rigidesa de la Constitució espanyola"},{"n":"6","title":"Les garanties institucionals: el Defensor del Poble"},{"n":"6.1","title":"Nomenament"},{"n":"6.2","title":"Funcions"},{"n":"7","title":"Les garanties jurisdiccionals"},{"n":"7.1","title":"El recurs d’empara ordinari"},{"n":"7.2","title":"El recurs d’empara constitucional"},{"n":"7.3","title":"El procediment de tutela dels drets que preveu el Conveni europeu de drets humans"},{"n":"8","title":"La suspensió dels drets constitucionals"},{"n":"8.1","title":"La suspensió general dels drets"},{"n":"8.2","title":"La suspensió individual dels drets"}]'::jsonb, '["La CE estableix que les normes relatives als drets fonamentals i a les llibertats s’han d’interpretar de conformitat amb la Declaració Universal dels Drets Humans i els tractats i acords internacionals sobre aquestes matèries.","Els drets constitucionals previstos a la CE poden classificar-se en: drets personals, drets de participació, drets econòmics i socials.","Els drets que han de ser respectats per garantir que els processos penals es desenvolupen d’acord amb la CE són els següents: dret a la llibertat, dret a la inviolabilitat del domicili, dret al secret de les comunicacions, dret a la tutela judicial efectiva.","Les garanties per a la protecció dels drets es classifiquen en tres grups: normatives (la vinculació de tots els poders públics als drets i les llibertats, el principi de reserva de llei i la rigidesa de la Constitució espanyola), institucionals (el Defensor del Poble) i jurisdiccionals (el recurs d’empara ordinari, el recurs d’empara constitucional i el procediment de tutela dels drets previst al Conveni europeu de drets humans).","La CE preveu que, en determinades situacions, és possible suspendre l’exercici d’alguns dels drets reconeguts. Aquesta possible suspensió ha de ser interpretada sempre de manera restrictiva atès que només es justifica en un estat democràtic per a la defensa dels drets constitucionals quan determinades accions limiten o impedeixen de fet el seu exercici, o posen en perill l’ordenament de la comunitat estatal."]'::jsonb, '["Actuar d’ofici o a instància de part","Assistència lletrada","Comparèixer","Comunitat política","Constitucionalista","Contenciós administratiu","Convicció","Dogmàtic","Dret natural","Drets constitucionals","Efectivitat","Escorcolls","Esfera privada de la ciutadania","Estat d’excepció","Estat de dret","Estat de setge","Estat social","Garanties normatives","Inalienable","Insurrecció","Internacionalització","Jurisprudència","Normatives civils","Pluralisme polític","Poder públic","Principi de preferència i sumarietat","Proves invàlides","Recurs subsidiari","Resolució desestimatòria","Resolució estimatòria","Suspensió general o individual","Titulars dels drets","Tutela ordinària dels drets","Voluntat estatal"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=129'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=129', 129, 141, 141, null
