insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Les Corts Generals"},{"n":"1.1","title":"Funcions"},{"n":"1.2","title":"L’autonomia de les cambres"},{"n":"1.3","title":"Composició del Congrés i del Senat"},{"n":"2","title":"El Govern"},{"n":"2.1","title":"Funcions"},{"n":"2.2","title":"Composició"},{"n":"2.3","title":"Nomenament i cessament dels membres del Govern"},{"n":"3","title":"La Corona"},{"n":"3.1","title":"Les funcions del rei"},{"n":"3.2","title":"L’estatut jurídic del rei"},{"n":"4","title":"Altres institucions de l’Estat"},{"n":"4.1","title":"El Tribunal de Comptes"},{"n":"4.2","title":"El Consell d’Estat"}]'::jsonb, '["Entenem per òrgans constitucionals aquells que són essencials per a l’existència del mateix Estat, de manera que la seva desaparició o transformació implica un canvi en l’estructura de l’Estat. En aquesta categoria s’inclouen: la Corona, les Corts Generals i el Govern.","Les Corts Generals són la suprema institució representativa del poble espanyol i tenen una estructura bicameral formada pel Congrés dels Diputats i el Senat.","La CE dota les Corts Generals d’una autonomia orgànica i funcional que es concreta en: autonomia reglamentària, autonomia de govern intern, autonomia administrativa i autonomia pressupostària.","El Congrés dels Diputats representa l’Estat atenent criteris de població. El nombre total de diputats es distribueix assignant a cada circumscripció un mínim inicial de dos diputats i la resta es distribueix en proporció a la població mitjançant una fórmula electoral.","El Senat és la cambra de representació territorial. La CE estableix dos mecanismes per a l’elecció dels senadors, però la seva composició no té un nombre fix, sinó que varia en funció de la població.","La CE preveu una sèrie de garanties perquè els membres de les Corts Generals puguin dur a terme les seves funcions d’una forma lliure i independent: la inviolabilitat i la immunitat.","El Govern és la institució encarregada de la direcció de la política interior i exterior de l’Estat. És un òrgan col·legiat, que actua sota la direcció del president o presidenta del Govern i a través del Consell de Ministres.","El Govern adopta una organització basada en el principi de jerarquia, ja que l’exercici del càrrec de ministre depèn directament de la decisió del seu president o presidenta i de la relació de confiança que hi hagi entre ells.","La forma política de govern de l’Estat espanyol és la monarquia parlamentària. La seva característica més important és que la configuració de la figura del cap de l’Estat es concreta en la institució de la Corona, de la qual el rei és el titular. La titularitat de la Corona és vitalícia i la seva successió es fa atenent criteris de transmissió hereditària. La inviolabilitat i la irresponsabilitat completen les característiques de la monarquia.","Els òrgans constitucionals de l’Estat compten amb l’ajuda d’uns òrgans d’assessorament tècnic que els auxilien en les seves tasques principals. D’entre els òrgans auxiliars cal destacar el Tribunal de Comptes i el Consell d’Estat."]'::jsonb, '["Aforament","Circumscripció electoral","Consell de Ministres","Contrasignats","Estructura bicameral","Fiscalitzar","Funció consultiva","Institució representativa","Investidura","Llistes electorals tancades i bloquejades","Majoria absoluta","Majoria simple","Monarquia parlamentària","Ordenament jurídic","Òrgan col·legiat","Òrgans constitucionals","Òrgans rectors","Preceptiu","Referendats","Responsabilitat solidària","Successió","Suplicatori","Transmissió hereditària","Vitalícia"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=142'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=142', 142, 149, 148, null
