insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Poder judicial i potestat jurisdiccional"},{"n":"1.1","title":"Principis configuradors del poder judicial"},{"n":"1.2","title":"Estatut dels jutges i magistrats"},{"n":"1.3","title":"Estructura del poder judicial"},{"n":"1.4","title":"El Tribunal Superior de Justícia de Catalunya"},{"n":"2","title":"El Consell General del Poder Judicial"},{"n":"2.1","title":"Composició del Consell General del Poder Judicial"},{"n":"2.2","title":"Funcions (article 560 de la Llei orgànica 4/2013, de 28 de juny, de reforma del Consell General del Poder Judicial)"},{"n":"3","title":"El Ministeri Fiscal"},{"n":"4","title":"El Tribunal Constitucional"},{"n":"4.1","title":"Composició del Tribunal Constitucional"},{"n":"4.2","title":"Competències del Tribunal Constitucional"}]'::jsonb, '["El poder judicial és un dels poders de l’Estat, independent dels altres poders (executiu i legislatiu), que té l’atribució de resoldre els conflictes en què hagi d’aplicar-se el dret i que es compon de jutges i magistrats.","Per poder exercir les seves funcions jurisdiccionals, el poder judicial té el suport de l’Administració de justícia. L’Administració de justícia no és poder judicial, sinó que comprèn el conjunt de mitjans personals i materials destinats a l’organització de les activitats relacionades amb la justícia, amb la finalitat de garantir el compliment de les funcions del poder judicial.","Els principis que configuren el poder judicial són: l’exclusivitat i la unitat jurisdiccional.","Els jutges i magistrats formen un cos únic i el seu estatut, que es regula a la Llei orgànica del poder judicial (LOPJ), es regeix pels principis següents: independència, inamovibilitat, imparcialitat, incompatibilitat i responsabilitat.","L’estructura del poder judicial es determina bàsicament per dos criteris: un de material, que obeeix a un principi d’especialització (civil, penal, contenciós administratiu i social), i un altre de territorial.","Les competències del Tribunal Superior de Justícia de Catalunya en relació amb el dret autonòmic se centren bàsicament a ser l’última instància jurisdiccional de tots els processos judicials iniciats a Catalunya, sens perjudici de la facultat reconeguda al Tribunal Suprem per unificació de doctrina. És també el màxim intèrpret del dret de Catalunya.","El Consell General del Poder Judicial (CGPJ) és l’òrgan de govern del poder judicial i té atribuïdes expressament les funcions relatives a nomenaments, ascensos, inspecció i règim disciplinari de jutges i magistrats.","El Ministeri Fiscal no forma part del poder judicial, però les seves funcions estan directament relacionades amb la funció jurisdiccional. És un òrgan únic a tot l’Estat. Exerceix les seves funcions mitjançant òrgans propis d’acord amb els principis d’unitat d’actuació, dependència jeràrquica i subjecció a la legalitat i imparcialitat.","El Fiscal General de l’Estat és nomenat pel rei a proposta del Govern, després d’haver escoltat el CGPJ, entre juristes de reconeguda competència.","El TC es crea amb l’objectiu principal d’establir un òrgan que vigili el respecte a la CE i depuri l’ordenament de les lleis i normes amb rang de llei que vulnerin la norma constitucional."]'::jsonb, '["Associació professional","Atribució","Autonomia local","Estatut jurídic","Funció jurisdiccional","Juristes","Jutge","Magistrat","Normes impugnades","Posicions doctrinals","Potestat jurisdiccional","Prevaricació","Qüestió d’inconstitucionalitat","Recurs d’inconstitucionalitat","Recursos de cassació","Recusació","Responsabilitat disciplinària"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=150'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=150', 150, 157, 157, null
