insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema B.7, pp. 158-166', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=158', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
insert into public.topics (slug, title) values ('mossos-b7-organitzacio-territorial', 'B.7 L''organització territorial de l''Estat') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'mossos-esquadra' and t.slug = 'mossos-b7-organitzacio-territorial' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Els models d’organització territorial"},{"n":"1.1","title":"L’Estat unitari i l’Estat federal"},{"n":"1.2","title":"L’evolució dels models"},{"n":"2","title":"El model territorial a la Constitució espanyola de 1978"},{"n":"3","title":"Les comunitats autònomes"},{"n":"4","title":"Els municipis"},{"n":"5","title":"Les províncies"},{"n":"6","title":"Les comarques"},{"n":"7","title":"Les vegueries"}]'::jsonb, '["En funció de quina sigui la forma de distribuir el poder en un Estat a través del seu territori, podem trobar dos “models” d’Estat: l’unitari i el federal.","El model unitari es basa fonamentalment en l’existència d’un únic centre de decisió política (el govern) i un únic centre per dictar normes amb rang de llei (el parlament) per a tot el territori de l’Estat. Els principis en què es basa són: la unitat (un sol Estat), la uniformitat (la mateixa llei per a tot el territori) i la centralització (direcció política i direcció administrativa efectuada des del centre).","L’Estat federal és un “Estat d’estats”, on el poder polític s’exerceix des de dues instàncies, la central (que és la federació), que disposa d’uns òrgans propis (parlament, president i tribunals) i que exerceix les seves funcions sobre tot el territori federal d’acord amb el que preveu la constitució federal; i les diferents instàncies territorials (els estats membres), que disposen cadascuna d’elles d’una constitució pròpia, d’una organització política pròpia i d’uns poders propis que exerceixen només sobre el seu territori.","L’Estat federal, a diferència de l’unitari, es caracteritza per tenir una pluralitat de centres de poder, una diversitat de normes i orientacions polítiques i una descentralització o distribució territorial de la capacitat de decisió.","La CE estableix uns principis i uns procediments que, en cas que siguin activats, han de permetre transformar l’Estat unitari i centralista espanyol en un Estat descentralitzat políticament i que pot adoptar diverses formes.","Les comunitats autònomes són aquelles entitats polítiques que, en exercici del dret a l’autonomia reconegut a la CE, gaudeixen de personalitat jurídica, de potestat d’autogovern i d’autonomia legislativa pròpia dins el seu àmbit territorial.","El municipi és la unitat local bàsica de l’organització territorial. Els ajuntaments són definits com a òrgans de govern local per als municipis, que són entitats territorials de dret públic.","La província és una entitat local amb personalitat jurídica pròpia, determinada per l’agrupació de municipis limítrofes, que constitueix una divisió territorial per al compliment de les activitats de l’Estat.","La vegueria és la divisió territorial adoptada per la Generalitat per a la futura organització territorial dels seus serveis.","La CE no crea la institució comarcal, però preveu la possibilitat que es creïn agrupacions de municipis diferents de la província. A més, habilita els estatuts d’autonomia per establir circumscripcions territorials pròpies a través de l’agrupació de municipis limítrofes que gaudiran de personalitat jurídica."]'::jsonb, '["Antic règim","Autonomia legislativa","Consell comarcal","Conveni","Diputacions","Divisió horitzontal de poder","Divisió vertical de poder","Estat compost","Estat sobirà","Estructura territorial","Idees racionalistes","Institucions locals","Model d’Estat","Personalitat jurídica","Poder polític","Potencial","Potestat d’autogovern","Prestació de servei","Regidors","Tributs","Uniformització"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=158'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=158', 158, 166, 165, null
  from public.topics t where t.slug = 'mossos-b7-organitzacio-territorial'
