insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema B.8, pp. 167-176', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=167', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
insert into public.topics (slug, title) values ('mossos-b8-unio-europea', 'B.8 La Unió Europea') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'mossos-esquadra' and t.slug = 'mossos-b8-unio-europea' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Origen històric de la Unió Europea"},{"n":"2","title":"L’ordenament jurídic comunitari: dret comunitari originari i dret derivat"},{"n":"2.1","title":"El dret comunitari originari"},{"n":"2.2","title":"El dret comunitari derivat"},{"n":"2.3","title":"Relacions entre el dret comunitari i el dret dels estats membres"},{"n":"3","title":"Institucions comunitàries"},{"n":"3.1","title":"El Consell de la Unió Europea"},{"n":"3.2","title":"La Comissió Europea"},{"n":"3.3","title":"El Parlament Europeu"},{"n":"3.4","title":"El Tribunal de Justícia de la Unió Europea"},{"n":"3.5","title":"Altres institucions comunitàries rellevants"}]'::jsonb, '["La Unió Europea és una organització supraestatal, basada en la unitat política, econòmica i monetària, construïda mitjançant la signatura de diversos tractats internacionals entre els països que en formen part.","El projecte inicial de comunitats europees no es conformava exclusivament amb la creació d’un únic espai econòmic, ni tampoc amb la presència dels estats signataris del Tractat de Roma de 1957, sinó que preveia la seva expansió en un doble sentit: ampliar el seu marc geogràfic amb la integració de nous estats, i aprofundir en les relacions entre els socis comunitaris per assolir una veritable unitat política, econòmica i monetària.","Les fonts del dret comunitari europeu es divideixen entre dret originari (o primari), format pels tractats constitutius de la Unió, i dret derivat (o secundari), constituït per tots els actes normatius dictats pels òrgans comunitaris.","El Consell de la Unió Europea és l’òrgan intergovernamental, en què els membres representen els interessos del seu Estat dins l’àmbit de la Unió Europea. Està integrat per un representant de cadascun dels estats membres. Les decisions del Consell s’adopten preferentment d’acord amb el principi de majoria qualificada, i s’introdueix un criteri ponderat mitjançant el qual s’assigna a cada Estat membre un nombre determinat de vots.","La Comissió Europea és un òrgan independent dels estats membres, i la seva missió és protegir i vetllar pels interessos comunitaris. Està integrada per vint-i-set membres, elegits per raó de la seva competència general sempre que ofereixin garanties d’independència.","El Parlament és l’òrgan que representa els pobles dels estats membres. Els escons es distribueixen entre els estats membres d’acord amb criteris de proporcionalitat en funció de la població. L’elecció dels parlamentaris es fa per sufragi universal directe a cadascun dels estats membres.","El Tribunal de Justícia és l’òrgan que garanteix la interpretació i aplicació del dret comunitari, i té un paper essencial en el desenvolupament del seu ordenament, atès que gran part de l’evolució d’aquest troba el seu fonament en decisions del Tribunal de Justícia."]'::jsonb, '["Acte de cessió de sobirania","Ampliació de la Unió Europea","Dictamen","Drets de duanes","Eficàcia jurídica","Jurisconsults","Organització supraestatal","Política d’asil","Tractat internacional","Vetar","Zona de lliure comerç"]'::jsonb, '[{"text":"Esmena oficial (setembre 2026): el Parlament Europeu té 720 membres.","url":"https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Esmenes-edicio-PDF-guia-estudi-setembre-2026.pdf"}]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=167'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=167', 167, 176, 176, null
