insert into public.sources (title, url, kind, publisher, published_on) values ('Guia d''estudi per accedir a la PG-ME, 1a edició, juny de 2026 (convocatòria 46/26), tema C.1, pp. 177-182', 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=177', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Mossos d''Esquadra (web oficial de la convocatòria 46/26)', '2026-06-01') on conflict (url) do nothing;
insert into public.topics (slug, title) values ('mossos-c1-competencies-seguretat', 'C.1 Competències de la Generalitat en seguretat') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'mossos-esquadra' and t.slug = 'mossos-c1-competencies-seguretat' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Definició de competència"},{"n":"2","title":"La competència en matèria de seguretat"},{"n":"2.1","title":"Les competències en matèria d’emergència i protecció civil"},{"n":"2.2","title":"Les competències en matèria de joc i espectacles"},{"n":"2.3","title":"Les competències en matèria de seguretat privada"},{"n":"2.4","title":"Les competències en matèria de seguretat pública"},{"n":"2.5","title":"Matèria de trànsit, circulació de vehicles i seguretat viària"}]'::jsonb, '["L’Estatut d’autonomia atorga competència a la Generalitat de Catalunya per crear una policia autònoma dins el marc del seu territori i li atorga no sols el comandament suprem d’aquesta nova policia, sinó també la coordinació de l’actuació de les policies locals o municipals.","La Generalitat de Catalunya assumeix, entre d’altres, una competència a hores d’ara prou clarificada: la protecció de persones i béns i el manteniment de l’ordre públic. Aquesta atribució competencial implica potestat per actuar en diversos àmbits: – Protecció civil i emergències (incloent-hi la prevenció i extinció d’incendis), salvament marítim i seguretat nuclear d’acord amb el contingut del nou Estatut. – Joc i espectacles. – Seguretat privada. – Policia, amb comandament directe sobre la Policia de la Generalitat - Mossos d’Esquadra i la coordinació de les policies locals. – Seguretat ciutadana i prevenció i investigació de delictes. – Trànsit i seguretat viària.","La responsabilitat de la Generalitat en aquest àmbit és territorial, és a dir, s’estén a tot el territori de Catalunya, en el marc del qual s’ubiquen les seves potestats i s’apliquen les seves normes. En conseqüència, és l’Administració l’encarregada de mantenir la cohesió territorial en matèria de seguretat, equilibrant les demandes i les necessitats locals i regionals quan puguin entrar en conflicte. El seu objectiu ha de ser mantenir nivells i serveis de seguretat homogenis a tot el territori."]'::jsonb, '["Competència","Matèria joc i espectacles","Protecció civil","Salvament marítim","Seguretat privada","Seguretat pública","Vigilància del trànsit"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=177'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=177', 177, 182, 182, null
