insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'mossos-esquadra' and t.slug = 'mossos-c2-departament-interior' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Funcions del Departament d’Interior i Seguretat Pública"},{"n":"2","title":"Estructura del Departament d’Interior i Seguretat Pública"},{"n":"3","title":"Funcions i estructura de la Direcció General de la Policia"},{"n":"4","title":"La Policia de la Generalitat - Mossos d’Esquadra"},{"n":"4.1","title":"Transformacions i evolució del cos de Mossos d’Esquadra"},{"n":"4.2","title":"Missió, visió i valors"},{"n":"4.3","title":"Compromisos amb la ciutadania"},{"n":"5","title":"L’Institut de Seguretat Pública de Catalunya"},{"n":"5.1","title":"Estructura de l’Institut de Seguretat Pública de Catalunya"},{"n":"5.2","title":"L’Escola de Policia de Catalunya"},{"n":"5.3","title":"L’Escola de Bombers, Protecció Civil i Agents Rurals de Catalunya"},{"n":"5.4","title":"La Subdirecció General d’Estudis Universitaris, Recerca i Desenvolupament"},{"n":"5.5","title":"La Subdirecció General d’Administració i Serveis"},{"n":"6","title":"El Servei Català de Trànsit"},{"n":"7","title":"Centre d’Atenció i Gestió de Trucades d’Urgència 112 Catalunya"}]'::jsonb, '["L’Institut de Seguretat Pública de Catalunya és l’encarregat d’estudiar la selecció i el procés formatiu exigible als cossos de policia i al personal de protecció del medi natural, de protecció civil i de prevenció i extinció d’incendis i de salvaments.","Depenen de l’Institut els òrgans següents: a) L’Escola de Policia de Catalunya. b) L’Escola de Bombers, Protecció Civil i Agents Rurals de Catalunya. c) La Subdirecció General d’Estudis Universitaris, Recerca i Desenvolupament. d) La Subdirecció General d’Administració i Serveis.","L’Escola de Policia de Catalunya dirigeix la detecció de les necessitats formatives, dissenya el contingut docent, i supervisa els processos d’avaluació dintre de l’àmbit de la seguretat.","L’Escola de Bombers, Protecció Civil i Agents Rurals de Catalunya dirigeix la detecció de les necessitats formatives, dissenya el contingut docent, i supervisa els processos d’avaluació dintre de l’àmbit de la prevenció, la protecció del medi natural i l’extinció d’incendis i de salvaments.","La Subdirecció General d’Administració i Serveis és responsable de la gestió integral dels recursos humans, econòmics, materials i jurídics de l’Institut, així com de la planificació pressupostària, la contractació i el manteniment de les infraestructures.","La Subdirecció General d’Estudis Universitaris, Recerca i Desenvolupament impulsa, coordina i gestiona la formació universitària, la recerca i la innovació en l’àmbit de la seguretat pública.","El Servei de Selecció i Avaluació és el responsable de planificar i d’executar l’avaluació del perfil de competències clau de l’alumnat dels cursos de formació bàsica de l’Institut.","La transferència de competències executives a la Generalitat en matèria de trànsit, circulació de vehicles i seguretat viària es va realitzar per la via de l’article 150.2 de la Constitució espanyola mitjançant la Llei orgànica de transferència de competències executives en matèria de trànsit i circulació de vehicles de motor a la Comunitat Autònoma de Catalunya.","El Servei Català de Trànsit és un organisme autònom de caràcter administratiu adscrit al Departament d’Interior i Seguretat Pública.","El Servei Català del Trànsit té adscrits l’Observatori de la Seguretat Viària, la Comissió Catalana de Trànsit i Seguretat Viària i la Comissió Inter departamental per a la millora de la Seguretat Viària.","El Centre d’Atenció i Gestió de Trucades d’Urgència 112 Catalunya és una entitat de dret públic dotada de personalitat jurídica pròpia i plena capacitat d’obrar per complir les seves funcions amb patrimoni i tresoreria propis i amb autonomia de gestió per assolir les seves finalitats, l’activitat del qual es regeix pel dret privat amb caràcter general.","El Centre d’Atenció i Gestió de Trucades d’Urgència 112 Catalunya s’adscriu al Departament d’Interior i Seguretat Pública, com a òrgan competent en matèria de seguretat pública."]'::jsonb, '["112","Adscripció","Assistència","Atenció","Avís","Centralització","Circulació de vehicles","Comandament operatiu","Competència","Consell de Direcció","Delinqüència ordinària, especialitzada i organitzada","Direcció General","Dret públic","Emergència","Extinció d’incendis","Gabinet del Conseller","Lliure exercici dels drets i llibertats","Mortalitat","Multa","Organisme autònom","Organisme","Organitzacions criminals","Percepció de seguretat","Pla estratègic","Protecció civil","Proximitat","Recursos humans","Recursos materials","Relacions amb la comunitat","Salvament","Sanció","Sancions disciplinàries","Secretaria General","Seguretat ciutadana","Seguretat pública","Seguretat viària","Serveis de gala i honors","Sub-direcció general","Telèfon únic","Transferència de competències executives","Trànsit","Trucada d’urgència","Urgència sanitària","Violència de gènere"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=183'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=183', 183, 204, 203, null
