insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"El concepte de coordinació policial"},{"n":"2","title":"La coordinació amb les forces i cossos de seguretat de l’Estat. La coordinació amb les policies locals de Catalunya"},{"n":"2.1","title":"La coordinació amb les forces i cossos de seguretat de l’Estat"},{"n":"2.2","title":"La coordinació amb les policies locals de Catalunya"},{"n":"3","title":"Els òrgans de coordinació establerts per la Llei 4/2003, de 7 d’abril, d’ordenació del sistema de seguretat pública de Catalunya"},{"n":"3.1","title":"Estructura del sistema de seguretat de Catalunya"},{"n":"4","title":"La cooperació policial internacional: Interpol i Europol"},{"n":"4.1","title":"La Interpol"},{"n":"4.2","title":"L’Europol"},{"n":"5","title":"Els acords internacionals en matèria de seguretat. El sistema d’informació Schengen (SIS)"},{"n":"5.1","title":"Objectius del SIS"},{"n":"5.2","title":"Estructura del SIS"},{"n":"5.3","title":"Funcionament del SIS"},{"n":"5.4","title":"El tractament de les dades informàtiques del SIS"},{"n":"5.5","title":"Competències de l’oficina SIRENE"}]'::jsonb, '["La seguretat es desenvolupa des dels diferents nivells de l’Administració pública: l’Estat, les comunitats autònomes i els ajuntaments. Aquesta competència compartida exigeix la coordinació entre els respectius cossos policials.","Un sistema de seguretat pública és el conjunt d’administracions, òrgans, autoritats i serveis que contribueixen a garantir la llibertat i la seguretat dels ciutadans i l’ordre públic.","L’article 164.2 de l’Estatut estableix que pertoca a la Generalitat el comandament suprem de la policia autònoma i la coordinació de l’actuació de les policies locals.","La coordinació en matèria policial entre la Policia de la Generalitat i les FCSE s’articula a través dels acords de la Junta de Seguretat de Catalunya.","Totes les funcions que l’ordenament jurídic atribueix al cos de Mossos d’Esquadra s’han de complir sota els principis de cooperació, coordinació i col·laboració mútua amb la resta de FCS.","En matèria de seguretat pública tenen competència l’Estat, les comunitats autònomes l’estatut d’autonomia de les quals ho preveu i que han exercit aquesta previsió, i les entitats locals. Atès que no es produeix una unificació de totes les competències en una sola entitat i, a més, no es dona exclusivitat a favor de cap administració, cal actuar d’acord amb els principis de cooperació, col·laboració i informació recíproca.","Coordinació entre la Generalitat i el Govern de l’Estat: Junta de Seguretat de Catalunya. La seva finalitat és coordinar les forces i cossos de seguretat de l’Estat i la Policia de la Generalitat - Mossos d’Esquadra.","Coordinació entre la Generalitat, el Govern de l’Estat i els ajuntaments: Junta Local de Seguretat. La coordinació de les policies locals correspon a la Generalitat, i és a les juntes locals de seguretat on s’adopten convenis de coordinació de la Policia de la Generalitat - Mossos d’Esquadra amb les entitats locals.","Coordinació entre la Generalitat i els ajuntaments: Comissió de Policia de Catalunya. És un òrgan consultiu que té com a funció elaborar informes dels projectes de coordinació que hagi d’aprovar el Govern de la Generalitat.","La Llei 4/2003, de 7 d’abril, posa les bases per dotar Catalunya d’un model de seguretat fonamentat en la prevenció, la participació i la implicació dels diferents serveis públics i privats, així com també de la societat civil.","El sistema de seguretat de Catalunya el constitueixen: les autoritats de seguretat, els cossos policials i els òrgans de coordinació i participació en matèria de seguretat.","La policia de les institucions pròpies de Catalunya està formada per les policies dels ajuntaments, ja siguin anomenades policia local, policia municipal, guàrdia urbana o d’altres maneres, i la Policia de la Generalitat - Mossos d’Esquadra.","La Llei crea i regula diferents òrgans de coordinació i participació: el Consell de Seguretat de Catalunya, la Comissió del Govern per a la Seguretat, la Comissió de Policia de Catalunya i les comissions regionals de seguretat. La Llei atorga una especial rellevància a les juntes locals de seguretat, que tenen caràcter obligatori en els municipis que disposin de policia local.","Coordinació entre la Generalitat i el Govern de l’Estat. Consell de Política de Seguretat: la seva finalitat és coordinar les polítiques de seguretat. Junta de Seguretat de Catalunya: la seva finalitat és coordinar les forces i cossos de seguretat de l’Estat i la Policia de la Generalitat - Mossos d’Esquadra.","Coordinació entre la Generalitat, el Govern de l’Estat i els ajuntaments: Junta Local de Seguretat. La coordinació de les policies locals correspon a la Generalitat i és a les juntes locals de seguretat on s’adopten convenis de coordinació i coordinació de la Policia de la Generalitat - Mossos d’Esquadra amb les entitats locals.","Coordinació entre la Generalitat i els ajuntaments: Comissió de Policia de Catalunya. És un òrgan consultiu que té com a funció elaborar informes dels projectes de coordinació que hagi d’aprovar el Govern de la Generalitat.","Un dels grans reptes als quals s’enfronta la societat actual és la globalització del crim organitzat. Aquesta nova forma de criminalitat implica que el comportament delictiu passi de ser una activitat local, patrimoni exclusiu d’uns quants, a ser-ho d’organitzacions delictives amb mitjans materials i tecnològics poderosos, sobretot amb la lliure circulació de persones i béns dins de l’àmbit comunitari.","La Interpol és una organització policial d’àmbit mundial que presta suport a les organitzacions, autoritats i serveis que tenen com a missió prevenir, detectar i combatre el delicte.","Els objectius generals de la Interpol són aconseguir i desenvolupar l’assistència recíproca entre les autoritats de policia criminal, i establir i desenvolupar tota una sèrie d’institucions.","A la Interpol, cada país membre disposa d’una oficina central nacional (OCN) que s’encarrega de mantenir l’enllaç amb els diversos serveis de policia de l’Estat respectiu, amb les oficines centrals nacionals dels altres països i amb la Secretaria General de l’organització. L’oficina central nacional (OCN) es compon de funcionaris de l’Estat, que actuen sempre dins del marc de la legislació nacional.","L’Europol neix amb la idea d’assolir una millora en la cooperació policial contra el terrorisme, el tràfic il·lícit de drogues i altres tipus de delinqüència internacional, mitjançant l’intercanvi d’informació permanent.","L’Europol té com a objectius millorar l’eficàcia i la cooperació entre les autoritats policials dels estats membres a fi i efecte de prevenir i lluitar contra el terrorisme, el tràfic il·lícit d’estupefaents, i de material radioactiu i nuclear, el tràfic d’éssers humans, el de vehicles, la immigració il·legal i el blanqueig de diners, sempre que hi hagi una estructura delictiva organitzada i que dos o més estats membres s’hi vegin afectats.","A l’Europol, cada Estat membre designa una unitat encarregada d’executar les funcions esmentades, que és l’únic òrgan d’enllaç entre l’Europol i els organismes i cossos policials dels estats membres.","L’objectiu de l’Acord de Schengen fou la creació d’una zona de lliure circulació, que implicava la supressió dels controls, tant de persones com de vehicles i mercaderies, a les fronteres comunes i l’establiment de tot un seguit de mecanismes i mesures de substitució per mantenir i incrementar els nivells de seguretat i control als països integrants.","El sistema integrat europeu d’informació d’interès policial té com a finalitat el manteniment d’un sistema europeu que permeti identificar persones, vehicles, armes de foc, documents i bitllets de banc, i proporcionar als agents que facin les identificacions les conductes que cal seguir en els supòsits d’una identificació positiva."]'::jsonb, '["Administració pública","Alcalde","Assistència mútua","Assistència recíproca","Àrea bàsica policial","Autoritats","Blanqueig de capital","Ciutadà extracomunitari","Col·laboració","Col·laboració mútua","Comissió de Policia de Catalunya","Comissió del Govern per a la Seguretat","Consell de Seguretat de Catalunya","Conveni de col·laboració","Cooperació","Cooperació recíproca","Coordinació","Crim organitzat","Criminalitat internacional","Delegats territorials del Govern","Delinqüència transnacional","Detenció preventiva","Extradició","Globalització","Globalització del crim","Informació recíproca","Intercanvi d’informació","Junta de Seguretat de Catalunya","Junta Local de Seguretat","Mesa de Coordinació Operativa","Oficina central nacional (OCN)","Òrgan executiu","Òrgans de coordinació i participació","Permisos de residència","Persona sospitosa","Pla general de seguretat de Catalunya","Pla local de seguretat","Policia judicial","Regió policial","Sala Interpolicial de Catalunya","Seguretat pública","Servei Nacional d’Intel·ligència Criminal - Europol (SNIC-Europol)","Sistema de seguretat pública","Substància estupefaent","Vigilància transfronterera","Visat"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=205'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=205', 205, 222, 220, null
