insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La Llei orgànica 2/1986, de 13 de març, de forces i cossos de seguretat. Principis bàsics d’actuació"},{"n":"1.1","title":"Principis bàsics d’actuació de les forces i els cossos de seguretat"},{"n":"2","title":"Llei 10/1994, d’11 de juliol, de la Policia de la Generalitat - Mossos d’Esquadra. Funcions, àmbit territorial d’actuació i estructura"},{"n":"2.1","title":"Definició de les competències"},{"n":"2.2","title":"Àmbit territorial d’actuació"},{"n":"2.3","title":"Estructura de la Policia de la Generalitat - Mossos d’Esquadra"},{"n":"3","title":"La Llei 16/1991, de 10 de juliol, de les policies locals de Catalunya. Funcions"},{"n":"3.1","title":"Funcions de la policia local"}]'::jsonb, '["L’objectiu principal de la Llei orgànica 2/1986 és el disseny de les línies mestres del règim jurídic de les FCS en el seu conjunt, i establir els principis bàsics d’actuació comuns i els seus criteris estatutaris fonamentals.","La constitució confereix a l’Estat la competència exclusiva sobre seguretat pública, que és exercida a través de les FCS. Les comunitats autònomes poden crear cossos policials en la forma que els respectius estatuts estableixin, i d’acord amb el marc legal de la mateixa Llei orgànica 2/1986.","Els cossos policials autonòmics són instituts armats de naturalesa civil amb organització jerarquitzada. De manera genèrica, tots els cossos autonòmics poden desenvolupar, a l’àmbit territorial que els correspongui, les funcions d’acord amb el seu règim competencial.","Els cossos policials autonòmics poden exercir les funcions recollides a l’article 38 de la Llei orgànica 2/1986 i que es delimiten com a funcions pròpies, funcions amb caràcter compartit i indiferenciat amb les FCSE i funcions de col·laboració amb altres FCSE.","Els principis bàsics d’actuació es poden ordenar en sis eixos fonamentals: l’adequació a l’ordenament jurídic, les relacions amb la comunitat, el tractament de les persones detingudes, la dedicació professional, el secret professional i la responsabilitat dels membres de les FCS.","Els principis bàsic recollits a la Llei orgànica 2/1986 s’han d’aplicar directament a la Policia de la Generalitat, així com les disposicions estatutàries comunes que estableixen els articles 6, 7 i 8.","La Llei 10/1994 té per objecte establir els principis d’actuació, les funcions i el règim funcionarial i estatutari dels membres de la Policia de la Generalitat - Mossos d’Esquadra, i l’organització de la seguretat pública en tot el territori, i preveu la creació dels òrgans necessaris i la dotació dels mitjans imprescindibles per al compliment correcte de les funcions de seguretat que corresponen a la Generalitat.","La policia no està per damunt de la Llei i, per tant, ha d’adequar la seva conducta a l’ordenament jurídic. El respecte que la policia deu a la societat l’obliga a utilitzar els recursos coactius solament en situacions extremes i amb una aplicació escrupolosa dels principis d’oportunitat, proporcionalitat i congruència.","La Policia de la Generalitat - Mossos d’Esquadra, com qualsevol altre cos de policia, té com a missió i divisa principal la protecció de la llibertat i la seguretat de la ciutadania.","La Policia de la Generalitat opera, amb tots els altres cossos, segons els principis de cooperació, coordinació i col·laboració mútua.","La Policia de la Generalitat - Mossos d’Esquadra té com a àmbit d’actuació el conjunt del territori de Catalunya.","Per a la implantació de la PG-ME, la unitat territorial bàsica és l’àrea bàsica policial (ABP), que és aquell territori definit per criteris operatius policials i que té la seva seu en una comissaria, des de la qual es donen els serveis policials bàsics en seguretat ciutadana i investigació.","La regió policial (RP) es defineix com l’àmbit territorial format per un conjunt d’ABP, sobre les quals ha d’exercir funcions de coordinació jeràrquica, suport en recursos operatius, logístics i especialitats i planificació d’àmbit superior a l’ABP.","La Policia de la Generalitat - Mossos d’Esquadra, com a policia ordinària i integral, exerceix les funcions que l’ordenament jurídic atribueix a les forces i els cossos de seguretat, i, en concret, les funcions de policia de seguretat ciutadana, policia administrativa i policia judicial.","La Policia de la Generalitat - Mossos d’Esquadra s’estructura jeràrquicament en les escales de suport, bàsica, intermèdia, executiva i superior.","La policia local és un cos de seguretat amb dependència de les corporacions locals, que participa en el manteniment de la seguretat pública. És un institut armat de naturalesa civil amb estructura i organització jerarquitzada.","Tots els municipis amb una població superior als 10.000 habitants poden crear cossos de policia local.","L’àmbit territorial d’actuació de la policia local és el territori del seu municipi, i excepcionalment, per raons d’emergència i sempre que en doni compte al conseller o consellera del Departament amb competències en matèria de seguretat pública, pot actuar en els municipis limítrofes.","Les policies locals s’estructuren en les escales i les categories superior, que comprèn les categories de superintendent, d’intendent major i d’intendent; l’escala executiva, que comprèn la categoria d’inspector; l’escala intermèdia, que comprèn les categories de sotsinspector i de sergent, i l’escala bàsica, que comprèn les categories de caporal i d’agent.","La Llei 16/1991, de 10 de juliol, de les policies locals de Catalunya, incorpora altres figures en matèria de seguretat per a aquells municipis que no disposin de policia local, i que són guàrdies, vigilants, agents, algutzirs o similars, que exerceixin les funcions custodia i vigilància, ordenar i regular trànsit, participar en les tasques d’auxili al ciutadà i de protecció civil, així com vetllar pel compliment de la normativa municipal.","Les policies locals s’han de regir pels principis bàsics d’actuació i per les disposicions estatutàries comunes que recull la Llei 2/1986, del 13 de març, de forces i cossos de seguretat, amb l’adequació necessària a l’Administració local, per les disposicions dictades per les comunitats autònomes i pels reglaments específics de cada cos i altres normes dictades pels ajuntaments corresponents.","Entre les funcions que la Llei atorga a la policia local destaquen la de policia administrativa, en l’observació del compliment de les normes municipals; la de policia de trànsit, en el nucli urbà, i la de protecció de les autoritats i instal·lacions municipals.","Les funcions de vigilància dels espais públics, l’auxili a la ciutadania, la prevenció dels delictes i el manteniment de l’ordre s’exerceixen de forma compartida o en règim de col·laboració amb altres cossos de seguretat."]'::jsonb, '["Àrea bàsica policial (ABP)","Comandament directe","Comandament operatiu","Comissaries generals","Comissió de Policia de Catalunya","Competència exclusiva","Competències concurrents","Congruència, oportunitat, proporcionalitat","Criminalística","Disposicions estatutàries","Eficàcia","Espai jurídic","Estructura jeràrquica","Estructures organitzatives","Funcions","Junta de Seguretat de Catalunya","Lliure exercici de drets","Mandat constitucional","Model de proximitat","Model descentralitzat","Norma ordenadora","Norma reguladora","Ordenament jurídic","Ordre organitzatiu descendent","Planificació estratègica","Policia administrativa","Policia de seguretat ciutadana","Policia integral","Policia judicial","Policia ordinària i integral","Prevenció","Principis bàsics d’actuació","Recursos operatius","Regió policial (RP)"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=223'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=223', 223, 237, 235, null
