insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La deontologia policial"},{"n":"2","title":"El Codi europeu d’ètica de la policia"},{"n":"3","title":"Acord GOV/25/2015, de 24 de febrer, pel qual s’aprova el Codi d’ètica de la Policia de Catalunya"}]'::jsonb, '["En un sistema democràtic, l’Estat i la policia no només han de respectar els drets humans, sinó que n’han de ser els garants i protectors.","El Consell d’Europa, a la Recomanació REC(2001)10, aconsella als seus estats membres seguir el Codi europeu d’ètica de la policia. Aquest Codi promou la cooperació internacional sobre les qüestions referides a l’ètica policial i els aspectes relacionats amb els drets humans.","El Codi europeu d’ètica de la policia es basa en el principi de la protecció de l’Estat de dret com a base de qualsevol democràcia veritable, i en la consideració que la policia, juntament amb el sistema penal, tenen un paper determinant en aquesta protecció.","El Codi d’ètica de la Policia de Catalunya no entra a reglamentar pràctiques policials concretes, sinó que és una eina pedagògica i inspiradora dirigida als cossos de policia de les institucions pròpies de Catalunya, que identifica els seus mínims ètics comuns, el conjunt de principis, valors i competències que inspiren la funció policial."]'::jsonb, '["Codi","Convivència","Deontologia","Discriminació","Drets humans","Estat de dret","Garant","Norma ètica","Proximitat","Pedagogia"]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=238'), 'https://mossos.gencat.cat/web/.content/home/01_els_mossos_desquadra/ingres-cos/Escala-bAsica/convocatoria-46-26/Guia_Mossos_Edicio_Juny_2026.pdf#page=238', 238, 242, 241, null
